// finding.go
// Package review — see env.go for package-level rationale.
//
// finding.go defines the structured-finding data model produced by the
// review pipeline. A Finding is immutable once recorded (spec §4); a fix is
// a separate append-only FixApplication, never a mutation of the Finding.
package review

import (
	"crypto/sha256"
	"encoding/hex"
	"strings"
)

// Severity is the finding severity. blocker/critical fold into high (spec §4).
type Severity string

const (
	SeverityHigh   Severity = "high"
	SeverityMedium Severity = "medium"
	SeverityLow    Severity = "low"
)

// Category is a fixed taxonomy + "other" (spec §4).
type Category string

const (
	CategorySecurity    Category = "security"
	CategoryCorrectness Category = "correctness"
	CategoryPerformance Category = "performance"
	CategoryTests       Category = "tests"
	CategoryDesign      Category = "design"
	CategoryReadability Category = "readability"
	CategoryOther       Category = "other"
)

// Finding is a structured piece of a reviewer's response. Immutable once recorded.
type Finding struct {
	ID         string   `json:"id"`
	File       string   `json:"file"`
	Line       int      `json:"line"`
	Severity   Severity `json:"severity"`
	Category   Category `json:"category"`
	Title      string   `json:"title"`
	Detail     string   `json:"detail"`
	Suggestion string   `json:"suggestion,omitempty"`
	Agent      string   `json:"agent"`
	Confidence float64  `json:"confidence,omitempty"` // set by verify (later PR); 0 here
}

// FixApplication is appended (never mutates a Finding) when an apply is attempted.
// Defined here so the persisted shape is stable; only written by later PRs.
type FixApplication struct {
	FindingID string `json:"finding_id"`
	Status    string `json:"status"` // applied | not_resolved | needs_human
	Fixer     string `json:"fixer,omitempty"`
	Verifier  string `json:"verifier,omitempty"`
	SHA       string `json:"sha,omitempty"`
}

// computeFindingID is the stable, content-anchored ID (spec §9, decision D1):
// sha256(file \0 enclosingSymbol \0 normalizedSnippet), hex, first 16 chars.
// Robust to line shifts; a rewritten snippet intentionally yields a new ID.
func computeFindingID(file, enclosingSymbol, snippet string) string {
	h := sha256.Sum256([]byte(file + "\x00" + enclosingSymbol + "\x00" + normalizeSnippet(snippet)))
	return hex.EncodeToString(h[:])[:16]
}

// fallbackFindingID (D3) is used only when there is no symbol and no line.
func fallbackFindingID(file string, cat Category, title string) string {
	h := sha256.Sum256([]byte(file + "\x00" + string(cat) + "\x00" + strings.TrimSpace(title)))
	return hex.EncodeToString(h[:])[:16]
}

// normalizeSnippet collapses all runs of whitespace to a single space and trims,
// so re-indentation / line moves don't change the ID.
func normalizeSnippet(s string) string {
	return strings.Join(strings.Fields(s), " ")
}
```

