// manifest.go
func buildLocalReviewManifestWithFindings(
	worktreeRoot, headSHA string,
	summary reviewtypes.RunSummary,
	states []*session.State,
	aggregateOutput string,
	provider PipelineProvider,
	diffContext string,
) LocalReviewManifest {
	m := buildLocalReviewManifestFromSummary(worktreeRoot, headSHA, summary, states, aggregateOutput)
	agents := make([]AgentOutput, 0, len(summary.AgentRuns))
	for _, run := range summary.AgentRuns {
		if out := agentRunOutput(run); out != "" {
			agents = append(agents, AgentOutput{Agent: run.Name, Output: out})
		}
	}
	if len(agents) == 0 {
		return m
	}
	rev, _ := provider.Structure(context.Background(), StructureInput{
		Agents: agents, DiffContext: diffContext, ScopeBaseRef: summaryScopeRef(summary),
	})
	m.Findings = rev.Findings
	m.Synthesis = rev.Synthesis
	return m
}
```

