// buildReviewDiffContext returns the file paths in scope (one per line) followed
// by the unified-diff hunk headers (lines beginning "@@"), used by the structuring
// provider to resolve File and the enclosing symbol for stable IDs (spec §9).
func buildReviewDiffContext(ctx context.Context, worktreeRoot, scopeBaseRef string) string {
	if scopeBaseRef == "" {
		return ""
	}
	rng := scopeBaseRef + "...HEAD"
	files, _ := runGit(ctx, worktreeRoot, "diff", "--name-only", rng)
	hunks, _ := runGit(ctx, worktreeRoot, "diff", "--unified=0", rng)
	var b strings.Builder
	b.WriteString(strings.TrimSpace(files))
	for _, ln := range strings.Split(hunks, "\n") {
		if strings.HasPrefix(ln, "@@") {
			b.WriteString("\n")
			b.WriteString(ln)
		}
	}
	return b.String()
}
```

