	if scopeBaseRef == "" {
		return ""
	}
	rng := scopeBaseRef + "...HEAD"
	files, _ := runGit(ctx, worktreeRoot, "diff", "--name-only", rng)
	hunks, _ := runGit(ctx, worktreeRoot, "diff", "--unified=0", rng)
	var b strings.Builder
	b.WriteString(strings.TrimSpace(files))
	for _, ln := range strings.Split(hunks, "\n") {
		if strings.HasPrefix(ln, "@@") {
			b.WriteString("\n")
			b.WriteString(ln)
		}
	}
	return b.String()
}
```

If deriving the diff proves noisy in PR #1, the acceptable fallback is to pass `diffContext=""` and document that §9 anchoring degrades to `Line=0` + the D3 fallback ID until a later PR — but do NOT pretend a `diffContext` variable already exists.

In `cmd.go`, at the manifest-writing call site in `runSingleAgentPath`, the `scopeBaseRef` is already computed for the banner — reuse it:

```go
provider := pipelineProviderFor(deps.PipelineProvider) // deps wired in review_bridge.go
diffContext := buildReviewDiffContext(ctx, worktreeRoot, scopeBaseRef)
manifest := buildLocalReviewManifestWithFindings(worktreeRoot, headSHA, summary, states, "", provider, diffContext)
_ = writeLocalReviewManifest(ctx, manifest)
```

Thread `PipelineProvider PipelineProvider` onto the review `Deps` struct (same place `SynthesisProvider`/`ReviewerFor` live).

