package review

import "testing"

func TestComputeFindingID_StableAcrossLineShift(t *testing.T) {
	t.Parallel()
	// Same file + enclosing symbol + snippet → same ID even if the line moved.
	a := computeFindingID("auth.go", "func check", "if tok == stored {")
	b := computeFindingID("auth.go", "func check", "if tok == stored {")
	if a != b || a == "" {
		t.Fatalf("expected stable non-empty id, got %q / %q", a, b)
	}
	if len(a) != 16 {
		t.Fatalf("id len = %d, want 16", len(a))
	}
}

func TestComputeFindingID_NormalizesWhitespace(t *testing.T) {
	t.Parallel()
	if computeFindingID("a.go", "f", "if x==y {") != computeFindingID("a.go", "f", "  if   x==y {  ") {
		t.Fatal("whitespace should be normalized")
	}
}

func TestComputeFindingID_DiffersByLocation(t *testing.T) {
	t.Parallel()
	if computeFindingID("a.go", "f", "x") == computeFindingID("b.go", "f", "x") {
		t.Fatal("different file must yield different id")
	}
}

func TestFallbackFindingID_UsedWhenNoAnchor(t *testing.T) {
	t.Parallel()
	id := fallbackFindingID("a.go", CategorySecurity, "token leak")
	if id == "" || len(id) != 16 {
		t.Fatalf("fallback id invalid: %q", id)
	}
}

