// Package review — see env.go for package-level rationale.
//
// pipeline.go implements the structuring pass (spec §5a, decision B1): it turns
// the reviewers' prose narratives + the in-scope diff into structured Findings
// plus a one-paragraph synthesis. The real provider calls a text generator; a
// deterministic fake is swapped in under ENTIRE_REVIEW_FAKE_PIPELINE for the
// canary (spec §13).
package review

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

// envFakePipeline swaps the model-backed provider for a deterministic stub
// (spec §13). Mirrors the ENTIRE_TEST_*/Vogon convention.
const envFakePipeline = "ENTIRE_REVIEW_FAKE_PIPELINE"

// osGetenv is indirected so the selector is testable without touching the env globally.
var osGetenv = os.Getenv

// AgentOutput is one reviewer's prose narrative for the run.
type AgentOutput struct {
	Agent  string
	Output string
}

// StructureInput is the find→verify seam input (spec §5a).
type StructureInput struct {
	Agents      []AgentOutput
	DiffContext string // file paths + hunk headers in scope (derived via git)
}

// StructuredReview is the structuring output: typed findings + a one-paragraph verdict.
type StructuredReview struct {
	Findings  []Finding
	Synthesis string
}

// PipelineProvider turns reviewer prose into structured findings + synthesis.
type PipelineProvider interface {
	Structure(ctx context.Context, in StructureInput) (StructuredReview, error)
}

// NewTextGenPipelineProvider builds the real provider from a text-generation
// function (the same seam lazySynthesisProvider uses).
func NewTextGenPipelineProvider(gen func(context.Context, string) (string, error)) PipelineProvider {
	return &textGenPipelineProvider{gen: gen}
}

// textGenPipelineProvider is the real provider: it composes a strict-JSON prompt
// and calls a text generator, then validates + applies the degrade rules.
type textGenPipelineProvider struct {
	gen func(ctx context.Context, prompt string) (string, error)
}

// rawStructure is the wire shape we ask the model to emit.
type rawStructure struct {
	Synthesis string `json:"synthesis"`
	Findings  []struct {
		File       string `json:"file"`
		Line       int    `json:"line"`
		Severity   string `json:"severity"`
		Category   string `json:"category"`
		Title      string `json:"title"`
		Detail     string `json:"detail"`
		Suggestion string `json:"suggestion"`
	} `json:"findings"`
}

func (p *textGenPipelineProvider) Structure(ctx context.Context, in StructureInput) (StructuredReview, error) {
	out, err := p.gen(ctx, composeStructurePrompt(in))
	if err != nil {
		return degradeToRaw(in), nil // never hard-fail a review (spec §5a)
	}
	var raw rawStructure
	if jsonErr := json.Unmarshal([]byte(extractJSON(out)), &raw); jsonErr != nil || len(raw.Findings) == 0 {
		return degradeToRaw(in), nil
	}
	files := diffFileSet(in.DiffContext)
	rev := StructuredReview{Synthesis: strings.TrimSpace(raw.Synthesis)}
	agent := primaryAgent(in)
	for _, rf := range raw.Findings {
		sev := normalizeSeverity(rf.Severity)
		cat := normalizeCategory(rf.Category)
		line := rf.Line
		if rf.File == "" || !files[rf.File] { // not in diff → file-level / not anchorable
			line = 0
		}
		id := computeFindingID(rf.File, enclosingSymbolFor(in.DiffContext, rf.File, line), rf.Title)
		if rf.File == "" && line == 0 {
			id = fallbackFindingID(rf.File, cat, rf.Title)
		}
		rev.Findings = append(rev.Findings, Finding{
			ID: id, File: rf.File, Line: line, Severity: sev, Category: cat,
			Title:      strings.TrimSpace(rf.Title),
			Detail:     strings.TrimSpace(rf.Detail),
			Suggestion: strings.TrimSpace(rf.Suggestion),
			Agent:      agent,
		})
	}
	return rev, nil
}

// degradeToRaw emits exactly one raw-prose finding (spec §5a degrade rule).
func degradeToRaw(in StructureInput) StructuredReview {
	var b strings.Builder
	for _, a := range in.Agents {
		b.WriteString(a.Output)
		b.WriteString("\n")
	}
	prose := strings.TrimSpace(b.String())
	return StructuredReview{
		Synthesis: "",
		Findings: []Finding{{
			ID:       fallbackFindingID("", CategoryOther, "Review output"),
			Severity: SeverityMedium,
			Category: CategoryOther,
			Title:    "Review output",
			Detail:   prose,
			Agent:    primaryAgent(in),
		}},
	}
}

// fakePipelineProvider is the deterministic canary stub (no model call).
type fakePipelineProvider struct{}

func (fakePipelineProvider) Structure(_ context.Context, in StructureInput) (StructuredReview, error) {
	f := Finding{
		File: "review_target.go", Line: 1, Severity: SeverityMedium, Category: CategoryCorrectness,
		Title: "vogon canary finding", Detail: "deterministic finding for the canary",
		Suggestion: "no-op", Agent: primaryAgent(in),
	}
