// Package review — see env.go for package-level rationale.
//
// results.go renders the post-run results for a structured review: the
// one-paragraph synthesis (the "read"), severity counts, and the flat
// findings list (the "act"). This is the single-agent path's authoritative
// post-run summary (spec §10 / walkthrough screen ③).
package review

import (
	"fmt"
	"io"
	"strings"
)

// severityCounts tallies findings by severity.
func severityCounts(fs []Finding) (high, med, low int) {
	for _, f := range fs {
		switch f.Severity {
		case SeverityHigh:
			high++
		case SeverityMedium:
			med++
		default:
			low++
		}
	}
	return high, med, low
}

// renderReviewResults prints the synthesis paragraph (if any), a one-line
// severity count, and the findings list. No-op when there are no findings.
func renderReviewResults(w io.Writer, m LocalReviewManifest) {
	if len(m.Findings) == 0 {
		return
	}
	if s := strings.TrimSpace(m.Synthesis); s != "" {
		fmt.Fprintln(w, s)
		fmt.Fprintln(w)
	}
	high, med, low := severityCounts(m.Findings)
	fmt.Fprintf(w, "%d findings · %d high · %d medium · %d low\n", len(m.Findings), high, med, low)
	for _, f := range m.Findings {
		loc := f.File
		if f.Line > 0 {
			loc = fmt.Sprintf("%s:%d", f.File, f.Line)
		}
		fmt.Fprintf(w, "  %-6s %-22s %s  (%s)\n", strings.ToUpper(string(f.Severity)), loc, f.Title, f.Agent)
	}
	if handle := reviewManifestHandle(m); handle != "" {
		fmt.Fprintln(w)
		fmt.Fprintf(w, "To apply:  %s review --fix %s --all\n", reviewCommandBinary, handle)
		fmt.Fprintf(w, "To choose: %s review --fix %s\n", reviewCommandBinary, handle)
	}
}

