package review

import (
	"context"
	"strings"
	"testing"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

func TestStructureFindings_FromProvider(t *testing.T) {
	t.Parallel()
	summary := reviewtypes.RunSummary{AgentRuns: []reviewtypes.AgentRun{{
		Name:   "vogon",
		Status: reviewtypes.AgentStatusSucceeded,
		Buffer: []reviewtypes.Event{reviewtypes.AssistantText{Text: "some review prose"}},
	}}}
	findings, syn := structureFindings(context.Background(), fakePipelineProvider{}, summary, "")
	if len(findings) == 0 || syn == "" {
		t.Fatalf("want findings + synthesis, got %d findings / synthesis %q", len(findings), syn)
	}
}

func TestStructureFindings_NilProviderYieldsNothing(t *testing.T) {
	t.Parallel()
	findings, syn := structureFindings(context.Background(), nil, reviewtypes.RunSummary{
		AgentRuns: []reviewtypes.AgentRun{{Name: "x", Buffer: []reviewtypes.Event{reviewtypes.AssistantText{Text: "y"}}}},
	}, "")
	if len(findings) != 0 || syn != "" {
		t.Fatal("nil provider must yield no findings and no synthesis")
	}
}

func TestRenderReviewResults_ShowsSynthesisCountsAndFindings(t *testing.T) {
	t.Parallel()
	m := LocalReviewManifest{
		Synthesis: "Recommend changes.",
		Findings: []Finding{
			{Severity: SeverityHigh, File: "auth.go", Line: 42, Title: "timing", Agent: "codex"},
			{Severity: SeverityLow, File: "c.go", Line: 9, Title: "nit", Agent: "claude"},
		},
	}
	var b strings.Builder
	renderReviewResults(&b, m)
	out := b.String()
	for _, want := range []string{"Recommend changes.", "2 findings", "1 high", "auth.go:42", "timing"} {
		if !strings.Contains(out, want) {
			t.Fatalf("output missing %q:\n%s", want, out)
		}
	}
}

// Package review — see env.go for package-level rationale.
//
// results.go renders the post-run results for a structured review: the
// one-paragraph synthesis (the "read"), severity counts, and the flat
// findings list (the "act"). This is the single-agent path's authoritative
// post-run summary (spec §10 / walkthrough screen ③).
package review

import (
	"fmt"
	"io"
	"strings"
)

// severityCounts tallies findings by severity.
func severityCounts(fs []Finding) (high, med, low int) {
	for _, f := range fs {
		switch f.Severity {
		case SeverityHigh:
			high++
		case SeverityMedium:
			med++
		case SeverityLow:
			low++
		default:
			low++
		}
	}
	return high, med, low
}

// renderReviewResults prints the synthesis paragraph (if any), a one-line
// severity count, and the findings list. No-op when there are no findings.
func renderReviewResults(w io.Writer, m LocalReviewManifest) {
	if len(m.Findings) == 0 {
		return
	}
	if s := strings.TrimSpace(m.Synthesis); s != "" {
		fmt.Fprintln(w, s)
		fmt.Fprintln(w)
	}
	high, med, low := severityCounts(m.Findings)
	fmt.Fprintf(w, "%d findings · %d high · %d medium · %d low\n", len(m.Findings), high, med, low)
	for _, f := range m.Findings {
		loc := f.File
		if f.Line > 0 {
			loc = fmt.Sprintf("%s:%d", f.File, f.Line)
		}
		fmt.Fprintf(w, "  %-6s %-22s %s  (%s)\n", strings.ToUpper(string(f.Severity)), loc, f.Title, f.Agent)
	}
	if handle := reviewManifestHandle(m); handle != "" {
		fmt.Fprintln(w)
		fmt.Fprintf(w, "To apply:  %s review --fix %s --all\n", reviewCommandBinary, handle)
		fmt.Fprintf(w, "To choose: %s review --fix %s\n", reviewCommandBinary, handle)
	}
}

