package review

import (
	"context"
	"testing"
)

type stubVerifyGen struct {
	out string
	err error
}

func (s stubVerifyGen) gen(_ context.Context, _ string) (string, error) { return s.out, s.err }

// verifyFuncProvider is a func-typed VerifyProvider test adapter.
type verifyFuncProvider func(Finding) bool

func (fn verifyFuncProvider) Verify(_ context.Context, f Finding, _ string) (VerifyResult, error) {
	return VerifyResult{Confirmed: fn(f)}, nil
}

func TestVerify_ParsesVerdict(t *testing.T) {
	t.Parallel()
	v := &textGenVerifyProvider{gen: stubVerifyGen{out: `{"confirmed":true}`}.gen}
	res, err := v.Verify(context.Background(), Finding{Title: "x", File: "a.go"}, "ctx")
	if err != nil || !res.Confirmed {
		t.Fatalf("want confirmed, got %+v err %v", res, err)
	}
}

func TestVerify_RefutesWhenFalse(t *testing.T) {
	t.Parallel()
	v := &textGenVerifyProvider{gen: stubVerifyGen{out: `{"confirmed":false}`}.gen}
	res, _ := v.Verify(context.Background(), Finding{Title: "x"}, "")
	if res.Confirmed {
		t.Fatal("want refuted")
	}
}

func TestVerify_DegradesToConfirmOnError(t *testing.T) {
	t.Parallel()
	// A verifier failure must not silently delete a real finding: degrade to
	// confirmed rather than dropping it (spec §7).
	v := &textGenVerifyProvider{gen: stubVerifyGen{err: context.DeadlineExceeded}.gen}
	res, _ := v.Verify(context.Background(), Finding{Title: "x"}, "")
	if !res.Confirmed {
		t.Fatal("verifier error must degrade to confirmed (never drop on failure)")
	}
}

func TestVerify_DegradesToConfirmOnBadJSON(t *testing.T) {
	t.Parallel()
	v := &textGenVerifyProvider{gen: stubVerifyGen{out: "I think this is fine"}.gen}
	res, _ := v.Verify(context.Background(), Finding{Title: "x"}, "")
	if !res.Confirmed {
		t.Fatal("unparseable verdict must keep the finding")
	}
}

func TestFakeVerifyProvider_Deterministic(t *testing.T) {
	t.Parallel()
	a, errA := fakeVerifyProvider{}.Verify(context.Background(), Finding{ID: "x"}, "")
	b, errB := fakeVerifyProvider{}.Verify(context.Background(), Finding{ID: "x"}, "")
	if errA != nil || errB != nil {
		t.Fatalf("fake verifier must not error: %v / %v", errA, errB)
	}
	if a.Confirmed != b.Confirmed {
		t.Fatal("fake verifier must be deterministic")
	}
}

func TestVerifyProviderFor_SelectsFakeViaEnv(t *testing.T) {
	t.Setenv(envFakePipeline, "1")
	if _, ok := verifyProviderFor(nil).(fakeVerifyProvider); !ok {
		t.Fatal("ENTIRE_REVIEW_FAKE_PIPELINE=1 must select the fake verifier")
	}
}

func TestVerifyFindings_DropsRefutedAndSetsConfidence(t *testing.T) {
	t.Parallel()
	findings := []Finding{
		{ID: "h", Severity: SeverityHigh, Title: "real"},
		{ID: "m", Severity: SeverityMedium, Title: "weak"},
	}
	// confirm high, refute medium
	vp := verifyFuncProvider(func(f Finding) bool { return f.Severity == SeverityHigh })
	got := verifyFindings(context.Background(), vp, findings, "")
	if len(got) != 1 || got[0].ID != "h" {
		t.Fatalf("refuted finding must be dropped: %+v", got)
	}
	if got[0].Confidence <= 0 || got[0].Confidence > 1 {
		t.Fatalf("confidence must be in (0,1]: %v", got[0].Confidence)
	}
}

func TestVerifyFindings_LowSeveritySkipsAndKeeps(t *testing.T) {
	t.Parallel()
	// low severity → 0 skeptics → kept with full confidence, verifier never called
	called := false
	vp := verifyFuncProvider(func(Finding) bool { called = true; return false })
	got := verifyFindings(context.Background(), vp, []Finding{{ID: "l", Severity: SeverityLow}}, "")
