// Package review — see env.go for package-level rationale.
//
// verify.go implements the adversarial verify phase (spec §7): each candidate
// finding is judged by independent skeptics that try to REFUTE it; only
// findings surviving a majority confirm are kept, each carrying a Confidence.
// This is the false-positive killer. A deterministic fake (selected by
// ENTIRE_REVIEW_FAKE_PIPELINE) keeps the canary API-free (spec §13).
package review

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// VerifyResult is one skeptic's verdict on a finding.
type VerifyResult struct {
	Confirmed bool
}

// VerifyProvider adversarially judges whether a candidate finding is real.
type VerifyProvider interface {
	Verify(ctx context.Context, f Finding, codeContext string) (VerifyResult, error)
}

// NewTextGenVerifyProvider builds the real verifier over a text-gen function
// (the same seam lazySynthesisProvider uses).
//
//nolint:ireturn // returns the VerifyProvider interface by design (injection seam)
func NewTextGenVerifyProvider(gen func(context.Context, string) (string, error)) VerifyProvider {
	return &textGenVerifyProvider{gen: gen}
}

type textGenVerifyProvider struct {
	gen func(ctx context.Context, prompt string) (string, error)
}

func (v *textGenVerifyProvider) Verify(ctx context.Context, f Finding, codeContext string) (VerifyResult, error) {
	out, err := v.gen(ctx, composeVerifyPrompt(f, codeContext))
	if err != nil {
		// Degrade to confirmed: a verifier failure must NEVER silently drop a
		// real finding (spec §7). Better a kept false positive than a dropped
		// true one.
		//nolint:nilerr // intentional graceful degrade on verifier failure
		return VerifyResult{Confirmed: true}, nil
	}
	var raw struct {
		Confirmed bool `json:"confirmed"`
	}
	if jsonErr := json.Unmarshal([]byte(extractJSON(out)), &raw); jsonErr != nil {
		// Unparseable verdict → keep the finding (same never-drop-on-failure rule).
		//nolint:nilerr // intentional graceful degrade on unparseable verdict
		return VerifyResult{Confirmed: true}, nil
	}
	// TEMP investigation logging (PR #2 verify tuning): what each skeptic said.
	raw2 := out
	if len(raw2) > 300 {
		raw2 = raw2[:300]
	}
	logging.Debug(ctx, "verify skeptic verdict",
		slog.String("finding", f.Title),
		slog.String("severity", string(f.Severity)),
		slog.Bool("confirmed", raw.Confirmed),
		slog.String("raw", raw2))
	return VerifyResult{Confirmed: raw.Confirmed}, nil
}

// fakeVerifyProvider is the deterministic canary stub: confirms everything.
type fakeVerifyProvider struct{}

func (fakeVerifyProvider) Verify(_ context.Context, _ Finding, _ string) (VerifyResult, error) {
	return VerifyResult{Confirmed: true}, nil
}

// verifyProviderFor returns the fake when ENTIRE_REVIEW_FAKE_PIPELINE is set,
// else the supplied real verifier.
//
//nolint:ireturn // returns the VerifyProvider interface by design (selector seam)
func verifyProviderFor(configured VerifyProvider) VerifyProvider {
	if strings.TrimSpace(osGetenv(envFakePipeline)) != "" {
		return fakeVerifyProvider{}
	}
	return configured
}

// skepticsFor returns how many independent skeptics verify a finding, by
// severity (spec §7 adaptive intensity): trivial skips, high gets the most.
func skepticsFor(sev Severity) int {
	switch sev {
	case SeverityHigh:
		return 3
	case SeverityMedium:
		return 1
	case SeverityLow:
		return 0 // trivial: skip verification, keep as-is
	default:
		return 1
	}
}

// verifyFindings runs the adaptive adversarial pass: each finding is judged by
// N independent skeptics; it survives only with majority confirmation, and its
// Confidence is the fraction confirming. A nil provider passes findings through
// unchanged (verify disabled).
func verifyFindings(ctx context.Context, vp VerifyProvider, findings []Finding, codeContext string) []Finding {
	if vp == nil {
		return findings
	}
	kept := make([]Finding, 0, len(findings))
	for _, f := range findings {
		n := skepticsFor(f.Severity)
		if n == 0 {
			f.Confidence = 1
			kept = append(kept, f)
			continue
		}
		confirms := 0
		for range n {
			res, err := vp.Verify(ctx, f, codeContext)
			if err != nil || res.Confirmed { // never drop on a verifier error (spec §7)
				confirms++
			}
		}
		kept2 := confirms*2 > n
		// TEMP investigation logging (PR #2 verify tuning): the per-finding tally.
		logging.Debug(ctx, "verify finding tally",
			slog.String("title", f.Title),
			slog.String("severity", string(f.Severity)),
			slog.Int("skeptics", n),
			slog.Int("confirms", confirms),
			slog.Bool("kept", kept2))
		if kept2 { // strict majority survives
			f.Confidence = float64(confirms) / float64(n)
			kept = append(kept, f)
		}
	}
	return kept
}

func composeVerifyPrompt(f Finding, codeContext string) string {
	var b strings.Builder
	b.WriteString("You are a skeptical reviewer. Try to REFUTE this finding. ")
	b.WriteString("Default to refuted (confirmed=false) if uncertain or if it is not a real issue. ")
	b.WriteString("Return ONLY {\"confirmed\": true|false}.\n\n")
	fmt.Fprintf(&b, "Finding: [%s] %s — %s\n%s\n", f.Severity, f.File, f.Title, f.Detail)
	if codeContext != "" {
		fmt.Fprintf(&b, "\nCode context:\n%s\n", codeContext)
	}
	return b.String()
}

