// Package review — see env.go for package-level rationale.
//
// verify.go implements the adversarial verify phase (spec §7): each candidate
// finding is judged by independent skeptics against the actual diff. A finding
// is dropped only on a majority REFUTE (a skeptic that saw the code and judged
// it a false positive); "uncertain" never drops a finding (never lose a real
// one to missing context). Survivors carry a Confidence = fraction confirming.
// A deterministic fake (selected by ENTIRE_REVIEW_FAKE_PIPELINE) keeps the
// canary API-free (spec §13).
package review

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
)

// Verdict is one skeptic's three-way judgement of a finding.
type Verdict string

const (
	VerdictConfirmed Verdict = "confirmed" // saw the code; the issue is real
	VerdictRefuted   Verdict = "refuted"   // saw the code; not a real issue (false positive)
	VerdictUncertain Verdict = "uncertain" // couldn't determine — keep, don't drop
)

// VerifyResult is one skeptic's verdict on a finding.
type VerifyResult struct {
	Verdict Verdict
}

// VerifyProvider adversarially judges whether a candidate finding is real.
type VerifyProvider interface {
	Verify(ctx context.Context, f Finding, codeContext string) (VerifyResult, error)
}

// NewTextGenVerifyProvider builds the real verifier over a text-gen function
// (the same seam lazySynthesisProvider uses).
//
//nolint:ireturn // returns the VerifyProvider interface by design (injection seam)
func NewTextGenVerifyProvider(gen func(context.Context, string) (string, error)) VerifyProvider {
	return &textGenVerifyProvider{gen: gen}
}

type textGenVerifyProvider struct {
	gen func(ctx context.Context, prompt string) (string, error)
}

func (v *textGenVerifyProvider) Verify(ctx context.Context, f Finding, codeContext string) (VerifyResult, error) {
	out, err := v.gen(ctx, composeVerifyPrompt(f, codeContext))
	if err != nil {
		// Never drop a finding on a verifier failure → uncertain (spec §7).
		//nolint:nilerr // intentional graceful degrade on verifier failure
		return VerifyResult{Verdict: VerdictUncertain}, nil
	}
	var raw struct {
		Verdict string `json:"verdict"`
	}
	if jsonErr := json.Unmarshal([]byte(extractJSON(out)), &raw); jsonErr != nil {
		//nolint:nilerr // unparseable verdict → uncertain (keep, never drop)
		return VerifyResult{Verdict: VerdictUncertain}, nil
	}
	return VerifyResult{Verdict: normalizeVerdict(raw.Verdict)}, nil
}

func normalizeVerdict(s string) Verdict {
	switch Verdict(strings.ToLower(strings.TrimSpace(s))) {
	case VerdictConfirmed:
		return VerdictConfirmed
	case VerdictRefuted:
		return VerdictRefuted
	case VerdictUncertain:
		return VerdictUncertain
	default:
		return VerdictUncertain
	}
}

// fakeVerifyProvider is the deterministic canary stub: confirms everything.
type fakeVerifyProvider struct{}

func (fakeVerifyProvider) Verify(_ context.Context, _ Finding, _ string) (VerifyResult, error) {
	return VerifyResult{Verdict: VerdictConfirmed}, nil
}

// verifyProviderFor returns the fake when ENTIRE_REVIEW_FAKE_PIPELINE is set,
// else the supplied real verifier.
//
//nolint:ireturn // returns the VerifyProvider interface by design (selector seam)
func verifyProviderFor(configured VerifyProvider) VerifyProvider {
	if strings.TrimSpace(osGetenv(envFakePipeline)) != "" {
		return fakeVerifyProvider{}
	}
	return configured
}

// skepticsFor returns how many independent skeptics verify a finding, by
// severity (spec §7 adaptive intensity): trivial skips, high gets the most.
func skepticsFor(sev Severity) int {
	switch sev {
	case SeverityHigh:
		return 3
	case SeverityMedium:
		return 1
	case SeverityLow:
		return 0 // trivial: skip verification, keep as-is
	default:
		return 1
	}
}

// verifyFindings runs the adaptive adversarial pass: each finding is judged by
// N independent skeptics. A finding is DROPPED only on a strict majority of
// REFUTE verdicts (skeptics that saw the code and called it a false positive);
// "uncertain" and "confirmed" both keep it. Confidence = fraction confirming.
// A nil provider passes findings through unchanged (verify disabled).
func verifyFindings(ctx context.Context, vp VerifyProvider, findings []Finding, codeContext string) []Finding {
	if vp == nil {
		return findings
	}
	kept := make([]Finding, 0, len(findings))
	for _, f := range findings {
		n := skepticsFor(f.Severity)
		if n == 0 {
			f.Confidence = 1
			kept = append(kept, f)
			continue
		}
		confirms, refutes := 0, 0
		for range n {
			res, err := vp.Verify(ctx, f, codeContext)
			switch {
			case err != nil:
				// treat as uncertain — never drop on error (spec §7)
			case res.Verdict == VerdictConfirmed:
				confirms++
			case res.Verdict == VerdictRefuted:
				refutes++
			}
		}
		if refutes*2 > n { // dropped only on a clear majority refute
			continue
		}
		f.Confidence = float64(confirms) / float64(n)
		kept = append(kept, f)
	}
	return kept
}

func composeVerifyPrompt(f Finding, codeContext string) string {
	var b strings.Builder
	b.WriteString("You are a skeptical code reviewer judging whether a reported finding is real, ")
	b.WriteString("using the diff below. Return ONLY {\"verdict\":\"confirmed|refuted|uncertain\"}: ")
	b.WriteString("\"confirmed\" = the diff clearly contains this issue; ")
	b.WriteString("\"refuted\" = you can see the relevant code and it is NOT a real issue (false positive); ")
	b.WriteString("\"uncertain\" = the diff doesn't contain enough to judge. Do NOT refute merely because you're unsure — use uncertain.\n\n")
	fmt.Fprintf(&b, "Finding: [%s] %s — %s\n%s\n", f.Severity, f.File, f.Title, f.Detail)
	if codeContext != "" {
		fmt.Fprintf(&b, "\nDiff under review:\n%s\n", codeContext)
	}
	return b.String()
}

