package review

import (
	"context"
	"testing"
)

type stubVerifyGen struct {
	out string
	err error
}

func (s stubVerifyGen) gen(_ context.Context, _ string) (string, error) { return s.out, s.err }

// verifyFuncProvider is a func-typed VerifyProvider test adapter returning a Verdict.
type verifyFuncProvider func(Finding) Verdict

func (fn verifyFuncProvider) Verify(_ context.Context, f Finding, _ string) (VerifyResult, error) {
	return VerifyResult{Verdict: fn(f)}, nil
}

func TestVerify_ParsesConfirmed(t *testing.T) {
	t.Parallel()
	v := &textGenVerifyProvider{gen: stubVerifyGen{out: `{"verdict":"confirmed"}`}.gen}
	res, err := v.Verify(context.Background(), Finding{Title: "x", File: "a.go"}, "diff")
	if err != nil || res.Verdict != VerdictConfirmed {
		t.Fatalf("want confirmed, got %+v err %v", res, err)
	}
}

func TestVerify_ParsesRefuted(t *testing.T) {
	t.Parallel()
	v := &textGenVerifyProvider{gen: stubVerifyGen{out: `{"verdict":"refuted"}`}.gen}
	res, _ := v.Verify(context.Background(), Finding{Title: "x"}, "")
	if res.Verdict != VerdictRefuted {
		t.Fatalf("want refuted, got %v", res.Verdict)
	}
}

func TestVerify_DegradesToUncertainOnError(t *testing.T) {
	t.Parallel()
	// A verifier failure must never drop a finding → uncertain (spec §7).
	v := &textGenVerifyProvider{gen: stubVerifyGen{err: context.DeadlineExceeded}.gen}
	res, err := v.Verify(context.Background(), Finding{Title: "x"}, "")
	if err != nil || res.Verdict != VerdictUncertain {
		t.Fatalf("verifier error must degrade to uncertain, got %+v err %v", res, err)
	}
}

func TestVerify_DegradesToUncertainOnBadJSON(t *testing.T) {
	t.Parallel()
	v := &textGenVerifyProvider{gen: stubVerifyGen{out: "I think this is fine"}.gen}
	res, _ := v.Verify(context.Background(), Finding{Title: "x"}, "")
	if res.Verdict != VerdictUncertain {
		t.Fatalf("unparseable verdict must be uncertain, got %v", res.Verdict)
	}
}

func TestFakeVerifyProvider_Confirms(t *testing.T) {
	t.Parallel()
	res, err := fakeVerifyProvider{}.Verify(context.Background(), Finding{ID: "x"}, "")
	if err != nil || res.Verdict != VerdictConfirmed {
		t.Fatalf("fake verifier must deterministically confirm, got %+v err %v", res, err)
	}
}

func TestVerifyProviderFor_SelectsFakeViaEnv(t *testing.T) {
	t.Setenv(envFakePipeline, "1")
	if _, ok := verifyProviderFor(nil).(fakeVerifyProvider); !ok {
		t.Fatal("ENTIRE_REVIEW_FAKE_PIPELINE=1 must select the fake verifier")
	}
}

func TestVerifyFindings_DropsRefutedAndSetsConfidence(t *testing.T) {
	t.Parallel()
	findings := []Finding{
		{ID: "h", Severity: SeverityHigh, Title: "real"},
		{ID: "m", Severity: SeverityMedium, Title: "weak"},
	}
	// confirm the high finding, refute the medium one
	vp := verifyFuncProvider(func(f Finding) Verdict {
		if f.Severity == SeverityHigh {
			return VerdictConfirmed
		}
		return VerdictRefuted
	})
	got := verifyFindings(context.Background(), vp, findings, "")
	if len(got) != 1 || got[0].ID != "h" {
		t.Fatalf("refuted finding must be dropped: %+v", got)
	}
	if got[0].Confidence != 1 { // 3/3 confirmed
		t.Fatalf("confidence should be 1, got %v", got[0].Confidence)
	}
}

func TestVerifyFindings_UncertainKeeps(t *testing.T) {
	t.Parallel()
	// All-uncertain must NOT drop the finding (never lose a real one to missing info).
	vp := verifyFuncProvider(func(Finding) Verdict { return VerdictUncertain })
	got := verifyFindings(context.Background(), vp, []Finding{{ID: "h", Severity: SeverityHigh, Title: "x"}}, "")
	if len(got) != 1 {
		t.Fatalf("uncertain must keep the finding, got %+v", got)
	}
	if got[0].Confidence != 0 { // 0/3 confirmed → low confidence, still shown
		t.Fatalf("uncertain confidence should be 0, got %v", got[0].Confidence)
	}
}

func TestVerifyFindings_LowSeveritySkipsAndKeeps(t *testing.T) {
	t.Parallel()
	called := false
	vp := verifyFuncProvider(func(Finding) Verdict { called = true; return VerdictRefuted })
	got := verifyFindings(context.Background(), vp, []Finding{{ID: "l", Severity: SeverityLow}}, "")
	if len(got) != 1 || got[0].Confidence != 1 {
		t.Fatalf("low severity must be kept with confidence 1: %+v", got)
	}
	if called {
		t.Fatal("low severity must skip the verifier")
	}
}

func TestVerifyFindings_NilProviderPassesThrough(t *testing.T) {
	t.Parallel()
	if got := verifyFindings(context.Background(), nil, []Finding{{ID: "x"}}, ""); len(got) != 1 {
		t.Fatal("nil verifier must pass findings through unchanged")
	}
}

