// Package review — see env.go for package-level rationale.
//
// phase.go defines the review pipeline's funnel phases and a single wrapper,
// runPipelinePhases, that runs structuring + verify while emitting PhaseUpdates
// to an observer (the live dashboard TUI in TTY mode; a no-op otherwise). The
// underlying structureFindings / verifyFindings are unchanged — the wrapper
// only orchestrates and narrates them (spec §10 funnel).
package review

import (
	"context"
	"fmt"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// Phase names the funnel stages surfaced in the dashboard.
type Phase string

const (
	PhaseFind       Phase = "find"
	PhaseVerify     Phase = "verify"
	PhaseSynthesize Phase = "synthesize"
)

// PhaseUpdate is one funnel transition for the dashboard.
type PhaseUpdate struct {
	Phase  Phase
	Done   bool
	Detail string // e.g. "9 candidates", "7 of 9 kept", "7 findings"
}

// PhaseObserver receives funnel updates. Use observe() so a nil observer is safe.
type PhaseObserver interface{ Phase(u PhaseUpdate) }

func observe(o PhaseObserver, u PhaseUpdate) {
	if o != nil {
		o.Phase(u)
	}
}

// runPipelinePhases runs structuring then adversarial verify over a finished
// run's narratives, emitting find/verify/synthesize updates to obs (nil-safe),
// and returns the final structured findings + synthesis. Detail strings use
// only counts observable here (candidate count, kept/total, final count) —
// verifyFindings returns survivors, not a confirm/refute split.
func runPipelinePhases(
	ctx context.Context,
	provider PipelineProvider,
	verifier VerifyProvider,
	summary reviewtypes.RunSummary,
	worktreeRoot, scopeBaseRef string,
	obs PhaseObserver,
) ([]Finding, string) {
	diffContext := buildReviewDiffContext(ctx, worktreeRoot, scopeBaseRef)
	findings, synthesis := structureFindings(ctx, provider, summary, diffContext)
	observe(obs, PhaseUpdate{Phase: PhaseFind, Done: true, Detail: fmt.Sprintf("%d candidates", len(findings))})

	before := len(findings)
	findings = verifyFindings(ctx, verifier, findings, buildReviewFullDiff(ctx, worktreeRoot, scopeBaseRef))
	observe(obs, PhaseUpdate{Phase: PhaseVerify, Done: true, Detail: fmt.Sprintf("%d of %d kept", len(findings), before)})

	observe(obs, PhaseUpdate{Phase: PhaseSynthesize, Done: true, Detail: fmt.Sprintf("%d findings", len(findings))})
	return findings, synthesis
}

