// pipelineLines renders the funnel panel (find → verify → synthesize). Empty
// until at least one phase update has arrived.
func (m reviewTUIModel) pipelineLines() []string {
	if len(m.phases) == 0 {
		return nil
	}
	lines := []string{"", "PIPELINE"}
	for _, p := range []Phase{PhaseFind, PhaseVerify, PhaseSynthesize} {
		st := m.phases[p]
		mark := "·"
		if st.done {
			mark = "✓"
		}
		lines = append(lines, fmt.Sprintf("  %s %-11s %s", mark, string(p), st.detail))
	}
	return lines
}

// findingsLines renders the findings panel. Empty until findings arrive.
func (m reviewTUIModel) findingsLines() []string {
	if len(m.findings) == 0 {
		return nil
	}
	high, med, low := severityCounts(m.findings)
	lines := []string{"", fmt.Sprintf("FINDINGS  %d · %d high · %d med · %d low", len(m.findings), high, med, low)}
	for i, f := range m.findings {
		cursor := "  "
		if i == m.findingIdx {
			cursor = "› "
		}
		loc := f.File
		if f.Line > 0 {
			loc = fmt.Sprintf("%s:%d", f.File, f.Line)
		}
		lines = append(lines, fmt.Sprintf("%s%-6s %-22s %s  %s %s",
			cursor, strings.ToUpper(string(f.Severity)), loc, f.Title, confidenceDots(f.Confidence), f.Agent))
	}
	return lines
}

