// buildFindingDetailLines renders one finding's detail (header meta, the why,
// and the suggested fix) as wrapped body lines for the finding-detail viewport.
func buildFindingDetailLines(f Finding, maxWidth int) []string {
	if maxWidth <= 0 {
		return nil
	}
	var lines []string
	add := func(s string) { lines = append(lines, wrapDisplayWidth(s, maxWidth)...) }
	loc := f.File
	if f.Line > 0 {
		loc = fmt.Sprintf("%s:%d", f.File, f.Line)
	}
	add(fmt.Sprintf("%s · %s · %s · %s · %s",
		strings.ToUpper(string(f.Severity)), loc, string(f.Category), confidenceDots(f.Confidence), f.Agent))
	if f.Detail != "" {
		add("")
		add(f.Detail)
	}
	if f.Suggestion != "" {
		add("")
		add("Suggested fix:")
		add("  " + f.Suggestion)
	}
	return lines
}

// findingDetailFrame renders the alt-screen chrome around a finding's detail
