// exactly bodyHeight lines, and a footer. Exactly termHeight lines.
func findingDetailFrame(f Finding, body string, termWidth, termHeight int) string {
	if termWidth < 1 {
		termWidth = 80
	}
	if termHeight < 3 {
		termHeight = 3
	}
	bodyHeight := termHeight - 2
	if bodyHeight < 0 {
		bodyHeight = 0
	}
	header := padDisplayWidthWith(fmt.Sprintf("─── %s ", sanitizeDisplayText(f.Title)), termWidth, "─")
	bodyLines := splitBodyToHeight(body, bodyHeight, termWidth)
	footer := padDisplayWidth("Esc/Ctrl+O: back · scroll: PgUp/PgDn/↑/↓/Home/End", termWidth)

	var b strings.Builder
	b.WriteString(header)
	b.WriteString("\n")
	for _, line := range bodyLines {
		b.WriteString(line)
		b.WriteString("\n")
	}
	b.WriteString(footer)
