	}
	switch {
	case msg.Mod == 0 && (msg.Code == tea.KeyUp || msg.Code == 'k'):
		if m.findingIdx > 0 {
			m.findingIdx--
		}
		return m, nil, true
	case msg.Mod == 0 && (msg.Code == tea.KeyDown || msg.Code == 'j'):
		if m.findingIdx < len(m.findings)-1 {
			m.findingIdx++
		}
		return m, nil, true
	case msg.Mod == 0 && msg.Code == ' ':
		if m.findingIdx < len(m.findingSel) {
			m.findingSel[m.findingIdx] = !m.findingSel[m.findingIdx]
		}
		return m, nil, true
	case msg.Code == 'a' && msg.Mod == tea.ModCtrl:
		for i := range m.findingSel {
			m.findingSel[i] = true
		}
		return m, nil, true
	case msg.Mod == 0 && msg.Code == tea.KeyEnter:
		// Enter applies the selected findings via the injected fixer.
		if m.applying || m.applied || m.apply == nil || m.selectedCount() == 0 {
			return m, nil, true
		}
		m.applying = true
		for i := range m.findingSel {
			if m.findingSel[i] {
				m.fixStatus[i] = "fixing"
			}
		}
		return m, m.apply(m.selectedFindings()), true
	}
	return m, nil, false
}

// selectedFindings returns the findings currently selected for apply.
func (m reviewTUIModel) selectedFindings() []Finding {
	out := make([]Finding, 0, m.selectedCount())
	for i, f := range m.findings {
		if i < len(m.findingSel) && m.findingSel[i] {
			out = append(out, f)
		}
	}
	return out
}

