		m.applying = true
		for i := range m.findingSel {
			if m.findingSel[i] {
				m.fixStatus[i] = "fixing"
			}
		}
		return m, m.apply(m.selectedFindings()), true
	}
	return m, nil, false
}

// selectedFindings returns the findings currently selected for apply.
func (m reviewTUIModel) selectedFindings() []Finding {
	out := make([]Finding, 0, m.selectedCount())
	for i, f := range m.findings {
		if i < len(m.findingSel) && m.findingSel[i] {
			out = append(out, f)
		}
	}
	return out
}

