func TestModel_ApplyFlow(t *testing.T) {
	t.Parallel()
	m := newReviewTUIModel([]string{"codex"}, func() {})
	m.termWidth, m.termHeight = 96, 30
	mm, _ := m.Update(findingsMsg{findings: []Finding{
		{ID: "h", Severity: SeverityHigh, File: "a.go", Line: 1, Title: "h", Agent: "codex"},
		{ID: "m", Severity: SeverityMedium, File: "a.go", Line: 2, Title: "m", Agent: "codex"},
	}})
	m = mustModel(t, mm)
	mm, _ = m.Update(runFinishedMsg{summary: reviewtypes.RunSummary{AgentRuns: []reviewtypes.AgentRun{{Name: "codex", Status: reviewtypes.AgentStatusSucceeded}}}})
	m = mustModel(t, mm)
	// Inject a fake fixer that marks every selected finding fixed.
	m.apply = func(sel []Finding) tea.Cmd {
		return func() tea.Msg {
			out := map[string]string{}
			for _, f := range sel {
				out[f.ID] = "fixed"
			}
			return fixDoneMsg{outcomes: out}
		}
	}
	mm, cmd := m.Update(testKey(tea.KeyEnter)) // enter → apply selected
	m = mustModel(t, mm)
	if !m.applying || m.fixStatus[0] != "fixing" {
		t.Fatalf("enter should start applying (fixing), got applying=%v status=%q", m.applying, m.fixStatus[0])
	}
	if cmd == nil {
		t.Fatal("enter should return an apply command")
	}
	mm, _ = m.Update(cmd()) // run the (fake) fixer → fixDoneMsg
	m = mustModel(t, mm)
	if !m.applied || m.fixStatus[0] != "fixed" {
		t.Fatalf("after fixDoneMsg: applied=%v status=%q", m.applied, m.fixStatus[0])
	}
	out := m.dashboardView()
	if !strings.Contains(out, "fixed ✓") || !strings.Contains(out, "✓ applied") {
		t.Fatalf("expected fixed status + applied footer:\n%s", out)
	}
	t.Logf("\n%s", out)
}
EOF
