// outcome map. Extracted from buildApplyFunc so the classification logic is
// unit-testable without driving a tea.Cmd.
func applyFixes(ctx context.Context, fixer Fixer, verifier VerifyProvider, worktreeRoot, scopeBaseRef string, selected []Finding) map[string]string {
