package review

import (
	"context"
	"strings"
	"testing"
)

// fakeFixer records the request and returns a configurable error.
type fakeFixer struct {
	err     error
	gotReq  FixRequest
	calls   int
}

func (f *fakeFixer) Fix(_ context.Context, req FixRequest) error {
	f.calls++
	f.gotReq = req
	return f.err
}

// verdictVerifier returns a fixed verdict per finding ID, modelling the
// post-fix re-verify: refuted → the issue is gone (fixed); confirmed → it still
// reproduces (needs-human).
type verdictVerifier map[string]Verdict

func (v verdictVerifier) Verify(_ context.Context, f Finding, _ string) (VerifyResult, error) {
	verdict, ok := v[f.ID]
	if !ok {
		verdict = VerdictConfirmed
	}
	return VerifyResult{Verdict: verdict}, nil
}

func TestApplyFixes_ClassifiesByReVerify(t *testing.T) {
	t.Parallel()
	// Two HIGH findings (skepticsFor(high) == 3, so verify actually runs):
	//   gone  → verifier refutes → dropped from survivors → fixed
	//   stays → verifier confirms → survives → needs-human
	gone := Finding{ID: "gone", Severity: SeverityHigh, Title: "g"}
	stays := Finding{ID: "stays", Severity: SeverityHigh, Title: "s"}
	fixer := &fakeFixer{}
	verifier := verdictVerifier{"gone": VerdictRefuted, "stays": VerdictConfirmed}

	out := applyFixes(context.Background(), fixer, verifier, t.TempDir(), "HEAD", []Finding{gone, stays})

	if out["gone"] != fixStatusFixed {
		t.Errorf("gone: got %q, want %q", out["gone"], fixStatusFixed)
	}
	if out["stays"] != fixStatusNeedsHuman {
		t.Errorf("stays: got %q, want %q", out["stays"], fixStatusNeedsHuman)
	}
	if fixer.calls != 1 {
		t.Errorf("fixer called %d times, want 1", fixer.calls)
	}
}

func TestApplyFixes_FixerErrorMarksAllFailed(t *testing.T) {
	t.Parallel()
	fixer := &fakeFixer{err: context.DeadlineExceeded}
	verifier := verdictVerifier{} // must not be consulted on fixer error
	findings := []Finding{{ID: "a", Severity: SeverityHigh}, {ID: "b", Severity: SeverityLow}}

	out := applyFixes(context.Background(), fixer, verifier, t.TempDir(), "HEAD", findings)

	for _, id := range []string{"a", "b"} {
		if out[id] != fixStatusFailed {
			t.Errorf("%s: got %q, want %q", id, out[id], fixStatusFailed)
		}
	}
}

func TestApplyFixes_NilVerifierReportsFixed(t *testing.T) {
	t.Parallel()
	// With no verifier we cannot tell whether the issue is gone; optimistically
	// report fixed (the user still sees the diff).
	fixer := &fakeFixer{}
	out := applyFixes(context.Background(), fixer, nil, t.TempDir(), "HEAD", []Finding{{ID: "x", Severity: SeverityHigh}})
	if out["x"] != fixStatusFixed {
		t.Errorf("x: got %q, want %q", out["x"], fixStatusFixed)
	}
}

func TestComposeHeadlessFixPrompt_IncludesSelectedFindings(t *testing.T) {
	t.Parallel()
	prompt := composeHeadlessFixPrompt([]Finding{
		{Severity: SeverityHigh, Title: "SQL injection", File: "db.go", Line: 42, Detail: "user input concatenated", Suggestion: "use parameters"},
	})
	for _, want := range []string{"SQL injection", "db.go:42", "HIGH", "user input concatenated", "use parameters", "Edit the files directly"} {
		if !strings.Contains(prompt, want) {
			t.Errorf("prompt missing %q\n---\n%s", want, prompt)
		}
	}
}

func TestBuildApplyFunc_NilFixerDisablesApply(t *testing.T) {
	t.Parallel()
	if buildApplyFunc(context.Background(), nil, nil, "", "") != nil {
		t.Error("buildApplyFunc with nil fixer should return nil (apply disabled)")
	}
}

func TestBuildApplyFunc_YieldsFixDoneMsg(t *testing.T) {
	t.Parallel()
	apply := buildApplyFunc(context.Background(), &fakeFixer{}, nil, t.TempDir(), "HEAD")
	if apply == nil {
		t.Fatal("buildApplyFunc returned nil for a non-nil fixer")
	}
	cmd := apply([]Finding{{ID: "x", Severity: SeverityHigh}})
	if cmd == nil {
		t.Fatal("apply returned a nil tea.Cmd")
	}
	msg, ok := cmd().(fixDoneMsg)
	if !ok {
		t.Fatalf("apply cmd yielded %T, want fixDoneMsg", cmd())
	}
	if msg.outcomes["x"] != fixStatusFixed {
		t.Errorf("outcome: got %q, want %q", msg.outcomes["x"], fixStatusFixed)
	}
}

