// Package review — see env.go for package-level rationale.
//
// agent_session.go handles the dominant surface: `entire review` invoked from
// inside a host coding agent's shell-out (Claude Code, Gemini, Copilot, Pi).
// In that surface there is no interactive terminal for a dashboard, and the
// host agent — which already has edit tools and a conversation the user is
// watching — is the right actor to perform fixes (every edit is visible). So
// entire orchestrates the *review* (fan-out + adversarial verify) and hands the
// host a directive to present the findings and fix the approved ones in-session,
// rather than spawning a hidden headless fixer the user can't see.
package review

import (
	"fmt"
	"io"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/provenance"
)

// hostAgentSentinels maps a host coding agent's env sentinel to its display
// name. Presence of the sentinel means we are running inside that agent's
// shell-out. Mirrors interactive.isAgentSubprocessEnv's vendor list, plus
// CLAUDECODE (Claude Code, the dominant host) which that TTY-focused helper
// intentionally omits.
var hostAgentSentinels = []struct{ env, name string }{
	{"CLAUDECODE", "Claude Code"},
	{"GEMINI_CLI", "Gemini"},
	{"COPILOT_CLI", "Copilot"},
	{"PI_CODING_AGENT", "Pi"},
}

// hostAgentName returns the display name of the host coding agent we are
// running inside, or "" when we are not in a recognised agent session.
//
// It returns "" inside a review-spawned agent (ENTIRE_REVIEW_SESSION=1): those
// child processes carry the host sentinel too, but they are reviewers, not the
// user's host session, and must not emit the present-and-fix directive.
func hostAgentName() string {
	if os.Getenv(provenance.ReviewSession) == "1" {
		return ""
	}
	for _, s := range hostAgentSentinels {
		if os.Getenv(s.env) != "" {
			return s.name
		}
	}
	return ""
}

// renderHostAgentDirective writes the in-session fix directive addressed to the
// host coding agent. It is plain text (the host reads it as command output, not
// a TTY) and intentionally imperative: the host should present the findings and
// fix the approved ones by editing files directly, where the user sees them.
func renderHostAgentDirective(w io.Writer, host string, findingCount int) {
	fmt.Fprintf(w, "\n─────────────────────────────────────────────\n")
	fmt.Fprintf(w, "Running inside a %s session. entire reviewed the changes and produced the %s above.\n", host, pluralFindings(findingCount))
	fmt.Fprintln(w, "Next steps for the agent:")
	fmt.Fprintln(w, "  1. Summarize the findings for the user, grouped by severity.")
	fmt.Fprintln(w, "  2. Ask which ones they want fixed.")
	fmt.Fprintln(w, "  3. Fix the approved findings by editing the files directly — your edits")
	fmt.Fprintln(w, "     are visible to the user. Keep changes minimal and targeted.")
	fmt.Fprintln(w, "The review and any fixes you commit are recorded on the current checkpoint.")
	fmt.Fprintf(w, "─────────────────────────────────────────────\n")
}

// pluralFindings renders "1 finding" / "N findings".
func pluralFindings(n int) string {
	if n == 1 {
		return "1 finding"
	}
	return fmt.Sprintf("%d findings", n)
}

