package review

import (
	"bytes"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/provenance"
)

func TestHostAgentName_DetectsClaudeCode(t *testing.T) {
	// Cannot t.Parallel: mutates process env (the detector reads os.Getenv).
	clearHostSentinels(t)
	t.Setenv("CLAUDECODE", "1")
	if got := hostAgentName(); got != "Claude Code" {
		t.Errorf("hostAgentName() = %q, want %q", got, "Claude Code")
	}
}

func TestHostAgentName_DetectsOtherHosts(t *testing.T) {
	for _, tc := range []struct{ env, want string }{
		{"GEMINI_CLI", "Gemini"},
		{"COPILOT_CLI", "Copilot"},
		{"PI_CODING_AGENT", "Pi"},
	} {
		t.Run(tc.env, func(t *testing.T) {
			clearHostSentinels(t)
			t.Setenv(tc.env, "1")
			if got := hostAgentName(); got != tc.want {
				t.Errorf("with %s set: hostAgentName() = %q, want %q", tc.env, got, tc.want)
			}
		})
	}
}

func TestHostAgentName_EmptyWhenNoSentinel(t *testing.T) {
	clearHostSentinels(t)
	if got := hostAgentName(); got != "" {
		t.Errorf("hostAgentName() = %q, want empty", got)
	}
}

func TestHostAgentName_EmptyInsideReviewSpawnedAgent(t *testing.T) {
	// A review-spawned reviewer carries the host sentinel too, but must not be
	// treated as the host session — the recursion guard suppresses the directive.
	clearHostSentinels(t)
	t.Setenv("CLAUDECODE", "1")
	t.Setenv(provenance.ReviewSession, "1")
	if got := hostAgentName(); got != "" {
		t.Errorf("inside review session: hostAgentName() = %q, want empty", got)
	}
}

func TestRenderHostAgentDirective_TellsHostToPresentAndFix(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
	renderHostAgentDirective(&buf, "Claude Code", 3)
	out := buf.String()
	for _, want := range []string{"Claude Code", "3 findings", "Summarize", "editing the files directly", "recorded on the current checkpoint"} {
		if !strings.Contains(out, want) {
			t.Errorf("directive missing %q\n---\n%s", want, out)
		}
	}
}

func TestRenderHostAgentDirective_SingularFinding(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
