// DumpSink writes per-agent narrative blocks to W after the run completes.
type DumpSink struct {
	W io.Writer
	// SuppressCounts omits the trailing "N agent(s) done" line. Set on the
	// single-agent path, where renderReviewResults is the authoritative
	// post-run summary (avoids a redundant second summary).
	SuppressCounts bool
}

// Compile-time interface check.
var _ reviewtypes.Sink = DumpSink{}

// AgentEvent is intentionally a no-op. DumpSink renders post-run from
// the AgentRun.Buffer slices in RunFinished.
func (DumpSink) AgentEvent(_ string, _ reviewtypes.Event) {}

// RunFinished writes a narrative block per agent, then a counts line.
func (s DumpSink) RunFinished(summary reviewtypes.RunSummary) {
	for _, run := range summary.AgentRuns {
		s.dumpAgent(run)
	}
	if !s.SuppressCounts {
		s.dumpCounts(summary)
	}
}

// dumpAgent composes one agent's section as markdown and writes it through
// mdrender. The counts line at the end of the run is intentionally NOT
// rendered through markdown — it's a terse status summary that benefits
// from staying on a single uncolored line for grep-ability.
//
// Markdown structure per agent:
//
//	# <name> review
//	(optional status line for cancelled / failed)
//	(optional blockquote for RunError events on failure)
//	(narrative — agent's AssistantText events joined)
func (s DumpSink) dumpAgent(run reviewtypes.AgentRun) {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s review\n\n", run.Name)

	switch run.Status {
	case reviewtypes.AgentStatusCancelled:
		b.WriteString("_cancelled_\n")
	case reviewtypes.AgentStatusFailed:
		// Surface the wait error if any (process exit failure), then any
		// agent-level RunError events the parser emitted (typically a torn
		// stdout stream — caught at the orchestrator level by classifyStatus
		// even when the process itself exited 0).
		writeFailureHeader(&b, run.Err)
		for _, ev := range run.Buffer {
			re, ok := ev.(reviewtypes.RunError)
			if !ok || re.Err == nil {
				continue
			}
			if sameFailureError(re.Err, run.Err) {
				continue
			}
			fmt.Fprintf(&b, "> agent error: `%v`\n\n", re.Err)
		}
		// Render any narrative text the agent produced before the failure
		// surfaced — useful when the parser tore mid-response so reviewers
		// can see partial output instead of a bare "(failed)" line.
		if narrative := joinAssistantText(run.Buffer); narrative != "" {
			b.WriteString(narrative)
			b.WriteString("\n")

// Update handles all incoming messages.
func (m reviewTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case agentEventMsg:
		return m.handleAgentEvent(msg)

	case phaseMsg:
		if m.phases == nil {
			m.phases = map[Phase]phaseState{}
		}
		m.phases[msg.update.Phase] = phaseState{done: msg.update.Done, detail: msg.update.Detail}
		return m, nil

	case findingsMsg:
		m.findings = msg.findings
		if m.findingIdx >= len(m.findings) {
			m.findingIdx = 0
		}
		// Default selection: all confirmed high + medium (low left off).
		m.findingSel = make([]bool, len(m.findings))
		m.fixStatus = make([]string, len(m.findings))
		for i, f := range m.findings {
			m.findingSel[i] = f.Severity == SeverityHigh || f.Severity == SeverityMedium
		}
		return m, nil

	case fixDoneMsg:
		m.applying = false
		m.applied = true
		for i := range m.findings {
			if st, ok := msg.outcomes[m.findings[i].ID]; ok {
				m.fixStatus[i] = st
			}
		}
		return m, nil

	case runFinishedMsg:
		m.finished = true
		m.summary = msg.summary
		// Sync each row's status from the orchestrator's summary. The
		// in-stream events (Finished / RunError) update status as they
		// arrive, but the orchestrator's classifyStatus has access to
		// process-level signals (Wait error, ctx cancellation) that the
		// event stream never surfaces. Without this sync, an agent that
		// the orchestrator classified Cancelled (Ctrl+C path, no Finished
		// emitted) or Failed (process exit non-zero, no Finished emitted)
		// would still render as "running" in the final frame.
		//
		// Preserve any already-set status from the event stream — if the
		// stream said Failed (RunError), the summary may say Succeeded
		// (process exit 0); RunError stickiness wins. Only overwrite when
		// the row is still in AgentStatusUnknown.
		now := time.Now()
		for i, run := range msg.summary.AgentRuns {
			if i >= len(m.rows) {
				break
			}
			if m.rows[i].status == reviewtypes.AgentStatusUnknown {
				m.rows[i].status = run.Status
			}
			if run.Tokens.In > 0 || run.Tokens.Out > 0 {
				m.rows[i].tokens = run.Tokens
			}
			if m.rows[i].err == nil && run.Err != nil {
				m.rows[i].err = run.Err
			}
			if m.rows[i].runEnd.IsZero() && !m.rows[i].runStart.IsZero() {
				m.rows[i].runEnd = now
			}
		}
		return m, nil

	case tickMsg:
		if m.finished {
			return m, nil
		}
		var spinCmd tea.Cmd
		m.spinner, spinCmd = m.spinner.Update(msg)
		return m, tea.Batch(spinCmd, tickCmd())

	case spinner.TickMsg:
		if m.finished {
			return m, nil
		}
		var spinCmd tea.Cmd
		m.spinner, spinCmd = m.spinner.Update(msg)
		return m, spinCmd

	case tea.WindowSizeMsg:
		wasAtBottom := m.detail.AtBottom()
		m.termWidth = msg.Width
		m.termHeight = msg.Height
		m.detail.SetWidth(m.detailViewportWidth())
		m.detail.SetHeight(m.detailViewportHeight())
		m = m.refreshDetailContentWithAutoTail(wasAtBottom)
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.MouseWheelMsg, tea.MouseClickMsg, tea.MouseReleaseMsg, tea.MouseMotionMsg:
		// Mouse events: only meaningful inside the drill-in viewport, which
		// handles tea.MouseWheelMsg natively.
		// Without this delegation the events arrive at the Program (because
		// View.MouseMode = MouseModeCellMotion is set during detail mode)
		// but fall through Update unhandled — the user sees no scroll
		// response to the wheel.
		if m.detailMode {
			var cmd tea.Cmd
			m.detail, cmd = m.detail.Update(msg)
			return m, cmd
		}
		return m, nil
	}
	return m, nil
}

