// pumpFixCmd reads one event from the live fix channel. It re-issues itself on
// each event (the standard Bubble Tea channel-drain pattern) and yields a
// fixClosedMsg once the channel closes.
func pumpFixCmd(events <-chan reviewtypes.Event) tea.Cmd {
	return func() tea.Msg {
		ev, ok := <-events
		if !ok {
			return fixClosedMsg{}
		}
		return fixEventMsg{ev: ev}
