// each event (the standard Bubble Tea channel-drain pattern) and yields a
// fixClosedMsg once the channel closes.
func pumpFixCmd(events <-chan reviewtypes.Event) tea.Cmd {
	return func() tea.Msg {
		ev, ok := <-events
		if !ok {
			return fixClosedMsg{}
		}
		return fixEventMsg{ev: ev}
	}
}

// handleFixEvent appends one live fix-stream event to the synthetic fix row's
// buffer, tracks the terminal Finished success, refreshes the drill-in if it is
// focused on the fix row, and keeps pumping the stream.
func (m reviewTUIModel) handleFixEvent(msg fixEventMsg) (tea.Model, tea.Cmd) {
	if m.fixRowIdx < 0 || m.fixRowIdx >= len(m.rows) {
		return m, nil
	}
	row := &m.rows[m.fixRowIdx]
	row.buffer = append(row.buffer, msg.ev)
	switch e := msg.ev.(type) {
	case reviewtypes.AssistantText:
		row.preview = truncateDisplayWidth(stringutil.CollapseWhitespace(sanitizeDisplayText(e.Text)), 80)
	case reviewtypes.Finished:
		m.fixSuccess = e.Success
	case reviewtypes.RunError:
		m.fixSuccess = false
	}
	if m.detailMode && m.detailIdx == m.fixRowIdx {
		m = m.refreshDetailContent()
	}
	return m, pumpFixCmd(m.fixEventsChan())
