package review

import (
	"context"
	"strings"
	"testing"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// fakeFixer returns a pre-seeded event stream (or a start error). It records the
// request so tests can assert prompt composition.
type fakeFixer struct {
	events    []reviewtypes.Event
	startErr  error
	gotReq    FixRequest
	callCount int
}

func (f *fakeFixer) Fix(_ context.Context, req FixRequest) (<-chan reviewtypes.Event, error) {
	f.callCount++
	f.gotReq = req
	if f.startErr != nil {
		return nil, f.startErr
	}
	ch := make(chan reviewtypes.Event, len(f.events))
	for _, ev := range f.events {
		ch <- ev
	}
	close(ch)
	return ch, nil
}

// verdictVerifier returns a fixed verdict per finding ID, modelling the post-fix
// re-verify: refuted → the issue is gone (fixed); confirmed → it still
// reproduces (needs-human).
type verdictVerifier map[string]Verdict

func (v verdictVerifier) Verify(_ context.Context, f Finding, _ string) (VerifyResult, error) {
	verdict, ok := v[f.ID]
	if !ok {
		verdict = VerdictConfirmed
	}
	return VerifyResult{Verdict: verdict}, nil
}

func TestClassifyOutcomes_ReVerifySplitsFixedAndNeedsHuman(t *testing.T) {
	t.Parallel()
	// Two HIGH findings (skepticsFor(high) == 3, so verify runs):
	//   gone  → verifier refutes → dropped from survivors → fixed
	//   stays → verifier confirms → survives → needs-human
	gone := Finding{ID: "gone", Severity: SeverityHigh, Title: "g"}
	stays := Finding{ID: "stays", Severity: SeverityHigh, Title: "s"}
	verifier := verdictVerifier{"gone": VerdictRefuted, "stays": VerdictConfirmed}

	out := classifyOutcomes(context.Background(), verifier, t.TempDir(), "HEAD", []Finding{gone, stays}, true)

	if out["gone"] != fixStatusFixed {
		t.Errorf("gone: got %q, want %q", out["gone"], fixStatusFixed)
	}
	if out["stays"] != fixStatusNeedsHuman {
		t.Errorf("stays: got %q, want %q", out["stays"], fixStatusNeedsHuman)
	}
}

func TestClassifyOutcomes_FixFailedMarksAllFailed(t *testing.T) {
	t.Parallel()
	verifier := verdictVerifier{} // must not be consulted on a failed run
	findings := []Finding{{ID: "a", Severity: SeverityHigh}, {ID: "b", Severity: SeverityLow}}
	out := classifyOutcomes(context.Background(), verifier, t.TempDir(), "HEAD", findings, false)
	for _, id := range []string{"a", "b"} {
		if out[id] != fixStatusFailed {
			t.Errorf("%s: got %q, want %q", id, out[id], fixStatusFailed)
		}
	}
}

func TestClassifyOutcomes_NilVerifierReportsFixed(t *testing.T) {
	t.Parallel()
	out := classifyOutcomes(context.Background(), nil, t.TempDir(), "HEAD", []Finding{{ID: "x", Severity: SeverityHigh}}, true)
	if out["x"] != fixStatusFixed {
		t.Errorf("x: got %q, want %q", out["x"], fixStatusFixed)
	}
}

func TestComposeHeadlessFixPrompt_IncludesSelectedFindings(t *testing.T) {
	t.Parallel()
	prompt := composeHeadlessFixPrompt([]Finding{
		{Severity: SeverityHigh, Title: "SQL injection", File: "db.go", Line: 42, Detail: "user input concatenated", Suggestion: "use parameters"},
	})
	for _, want := range []string{"SQL injection", "db.go:42", "HIGH", "user input concatenated", "use parameters", "Edit the files directly"} {
		if !strings.Contains(prompt, want) {
			t.Errorf("prompt missing %q\n---\n%s", want, prompt)
		}
	}
}

func TestBuildApplyFunc_NilFixerDisablesApply(t *testing.T) {
	t.Parallel()
	if buildApplyFunc(context.Background(), nil, nil, "", "") != nil {
		t.Error("buildApplyFunc with nil fixer should return nil (apply disabled)")
	}
}

func TestBuildApplyFunc_YieldsFixStreamMsg(t *testing.T) {
	t.Parallel()
	fixer := &fakeFixer{events: []reviewtypes.Event{reviewtypes.Finished{Success: true}}}
	apply := buildApplyFunc(context.Background(), fixer, nil, t.TempDir(), "HEAD")
	if apply == nil {
		t.Fatal("buildApplyFunc returned nil for a non-nil fixer")
	}
	cmd := apply([]Finding{{ID: "x", Severity: SeverityHigh}})
	if cmd == nil {
		t.Fatal("apply returned a nil tea.Cmd")
	}
	stream, ok := cmd().(fixStreamMsg)
	if !ok {
		t.Fatalf("apply cmd yielded %T, want fixStreamMsg", cmd())
	}
	if stream.events == nil || stream.verify == nil {
		t.Fatalf("fixStreamMsg missing events/verify: %+v", stream)
	}
	if fixer.callCount != 1 {
		t.Errorf("fixer called %d times, want 1", fixer.callCount)
	}
}

func TestBuildApplyFunc_StartErrorYieldsFailedFixDone(t *testing.T) {
	t.Parallel()
	fixer := &fakeFixer{startErr: context.DeadlineExceeded}
	apply := buildApplyFunc(context.Background(), fixer, nil, t.TempDir(), "HEAD")
	msg := apply([]Finding{{ID: "x", Severity: SeverityHigh}})()
	done, ok := msg.(fixDoneMsg)
	if !ok {
		t.Fatalf("start error yielded %T, want fixDoneMsg", msg)
	}
	if done.outcomes["x"] != fixStatusFailed {
		t.Errorf("outcome: got %q, want %q", done.outcomes["x"], fixStatusFailed)
	}
}

