// Enter → fixStreamMsg → live events fill the fix row (auto-drilled-in) →
// stream close → re-verify → fixDoneMsg flips the finding to fixed.
func TestModel_StreamingApplyFlow(t *testing.T) {
	t.Parallel()
	m := newReviewTUIModel([]string{"codex"}, func() {}, nil)
	m.termWidth, m.termHeight = 96, 30
	mm, _ := m.Update(findingsMsg{findings: []Finding{
		{ID: "h", Severity: SeverityHigh, File: "a.go", Line: 1, Title: "boom", Agent: "codex"},
	}})
	m = mustModel(t, mm)

	// Real apply func over a fake streaming fixer (one assistant line + success)
	// and nil verifier (→ optimistic fixed).
	fixer := &fakeFixer{events: []reviewtypes.Event{
		reviewtypes.AssistantText{Text: "editing a.go: add zero guard"},
		reviewtypes.Finished{Success: true},
	}}
	m.apply = buildApplyFunc(context.Background(), fixer, nil, t.TempDir(), "HEAD")

	mm, cmd := m.Update(testKey(tea.KeyEnter)) // enter → apply
