package claudecode

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// NewFixer returns the streaming headless Fixer for claude-code used by the
// review dashboard's in-dashboard apply flow.
//
// It runs `claude -p <prompt> --output-format stream-json --verbose
// --permission-mode acceptEdits` in the worktree and adapts the stdout through
// the SAME parser the reviewer uses (parseClaudeOutput), so the fixer's edits
// and reasoning surface as the same Event stream the dashboard already renders.
// The -p (print) mode is non-interactive: claude never prompts for input, so it
// coexists with the Bubble Tea dashboard that owns the terminal. acceptEdits
// auto-accepts file edits (the fixer's core need) without granting broader tool
// access; tools that still need permission are denied rather than blocking.
//
//nolint:ireturn // returns the review.Fixer interface by design (injection seam, mirrors NewReviewer)
func NewFixer() review.Fixer {
	return claudeFixer{}
}

type claudeFixer struct{}

func (claudeFixer) Fix(ctx context.Context, req review.FixRequest) (<-chan reviewtypes.Event, error) {
	cmd := exec.CommandContext(ctx, "claude", "-p", req.Prompt,
		"--output-format", "stream-json", "--verbose", "--permission-mode", "acceptEdits")
	cmd.Dir = req.WorktreeRoot
	cmd.Env = withoutReviewEnv(os.Environ())

	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, fmt.Errorf("claude fix stdout pipe: %w", err)
	}
	if err := cmd.Start(); err != nil {
		return nil, fmt.Errorf("start claude fix: %w", err)
	}

	parsed := parseClaudeOutput(stdout)
	out := make(chan reviewtypes.Event)
	go func() {
		defer close(out)
		for ev := range parsed {
			out <- ev
		}
		// Reap the process after the stream drains. The terminal Finished event
		// (from the result envelope) is the source of truth for success, so the
		// Wait error is intentionally swallowed — a non-zero exit with a clean
		// result envelope still means the fix ran.
		_ = cmd.Wait()
	}()
	return out, nil
}

// withoutReviewEnv strips the ENTIRE_REVIEW_* / ENTIRE_INVESTIGATE_* handshake
// vars so the fix session is not tagged as a review/investigate session by the
// lifecycle hooks (mirrors agentlaunch's env hygiene for fix sessions).
func withoutReviewEnv(env []string) []string {
	out := make([]string, 0, len(env))
	for _, kv := range env {
		if strings.HasPrefix(kv, "ENTIRE_REVIEW_") || strings.HasPrefix(kv, "ENTIRE_INVESTIGATE_") {
			continue
		}
		out = append(out, kv)
	}
	return out
}

