package review

import (
	"os"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/provenance"
)

// TestMain clears the host-agent sentinels (and the review recursion guard)
// before the package's tests run, so hostAgentName() detection is deterministic
// whether the suite runs under a host coding agent — e.g. CLAUDECODE is set when
// tests run inside a Claude Code session — or in CI. Tests that exercise
// agent-session behavior opt back in explicitly with t.Setenv.
func TestMain(m *testing.M) {
	for _, env := range []string{"CLAUDECODE", "GEMINI_CLI", "COPILOT_CLI", "PI_CODING_AGENT", provenance.ReviewSession} {
		if err := os.Unsetenv(env); err != nil {
			panic("clear sentinel " + env + ": " + err.Error())
		}
	}
	os.Exit(m.Run())
}

