// Package review — see env.go for package-level rationale.
//
// fix_headless.go provides the terminal-dashboard apply path: a streaming
// headless Fixer seam and the apply func the TUI model invokes when the user
// presses Enter on selected findings. Two load-bearing words:
//
//   - "headless" — the fixer must run without owning the terminal, because the
//     Bubble Tea dashboard already does. The interactive agentlaunch.LaunchFixAgent
//     inherits stdio and would fight the TUI for the TTY.
//   - "streaming" — the fixer emits events as it works so the dashboard can show
//     WHAT it is doing (edits/reasoning) in the drill-in, not just "fixing…".
//
// This path is the bare-terminal surface only. In an agent session the host
// agent performs the fix in-conversation (see agent_session.go); there is no
// dashboard and this apply func is never wired.
package review

import (
	"context"
	"fmt"
	"strings"

	tea "charm.land/bubbletea/v2"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// Fixer applies fixes for selected findings without owning the terminal, and
// streams its work as events so the dashboard can render it live. Implementations
// spawn their agent headlessly (e.g. `claude -p <prompt> --output-format
// stream-json --permission-mode acceptEdits`) and adapt its output into the same
// Event stream the reviewers use. Implemented per-agent (claudecode.NewFixer)
// and injected via Deps.FixerFor to avoid the review → agent import cycle.
type Fixer interface {
	// Fix starts the fixer and returns a channel of events that closes when the
	// fix run completes. The terminal Finished event's Success reports the
	// outcome. A non-nil error means the fixer could not start at all.
	Fix(ctx context.Context, req FixRequest) (<-chan reviewtypes.Event, error)
}

// FixRequest carries the composed fix prompt and the worktree the fixer edits.
type FixRequest struct {
	Prompt       string
	WorktreeRoot string
}

// buildApplyFunc returns the model's apply func: given the user-selected
// findings, it composes a fix prompt and starts the streaming headless fixer.
// The returned tea.Cmd yields a fixStreamMsg carrying the live event channel and
// a verify closure the model invokes once the stream closes (re-verifying the
// findings against the post-fix code to classify fixed vs needs-human). If the
// fixer cannot start, it yields a fixDoneMsg marking every selection failed.
//
// Returns nil when no fixer is available, which leaves the model's apply field
// nil and disables in-dashboard apply (Enter just exits).
func buildApplyFunc(ctx context.Context, fixer Fixer, verifier VerifyProvider, worktreeRoot, scopeBaseRef string) func([]Finding) tea.Cmd {
	if fixer == nil {
		return nil
	}
	return func(selected []Finding) tea.Cmd {
		return func() tea.Msg {
			events, err := fixer.Fix(ctx, FixRequest{Prompt: composeHeadlessFixPrompt(selected), WorktreeRoot: worktreeRoot})
			if err != nil {
				return fixDoneMsg{outcomes: classifyOutcomes(ctx, verifier, worktreeRoot, scopeBaseRef, selected, false)}
			}
			return fixStreamMsg{
				events: events,
				verify: func(fixSucceeded bool) map[string]string {
					return classifyOutcomes(ctx, verifier, worktreeRoot, scopeBaseRef, selected, fixSucceeded)
				},
			}
		}
	}
}

// classifyOutcomes returns a per-ID outcome map for the selected findings after
// a fix run. On a failed run every finding is failed. On success it re-verifies
// against the post-fix code: a finding that no longer reproduces is fixed; one
// that still reproduces needs a human. With no verifier we cannot tell, so we
// optimistically report fixed (the user still sees the diff).
func classifyOutcomes(ctx context.Context, verifier VerifyProvider, worktreeRoot, scopeBaseRef string, selected []Finding, fixSucceeded bool) map[string]string {
	outcomes := make(map[string]string, len(selected))
	if !fixSucceeded {
		for _, f := range selected {
			outcomes[f.ID] = fixStatusFailed
		}
		return outcomes
	}
	stillReproduces := map[string]bool{}
	if verifier != nil {
		postFixDiff := buildReviewFullDiff(ctx, worktreeRoot, scopeBaseRef)
		for _, f := range verifyFindings(ctx, verifier, selected, postFixDiff) {
			stillReproduces[f.ID] = true
		}
	}
	for _, f := range selected {
		if stillReproduces[f.ID] {
			outcomes[f.ID] = fixStatusNeedsHuman
		} else {
			outcomes[f.ID] = fixStatusFixed
		}
	}
	return outcomes
}

// composeHeadlessFixPrompt builds the fix instruction for the selected findings.
// It is intentionally terse and directive: the fixer runs headlessly, so the
// prompt must stand alone with no follow-up turns.
func composeHeadlessFixPrompt(selected []Finding) string {
	var b strings.Builder
	b.WriteString("Fix only the review findings listed below. Edit the files directly.\n")
	b.WriteString("Keep changes minimal and targeted — do not rewrite unrelated code.\n")
	for i, f := range selected {
		loc := f.File
		if f.Line > 0 {
			loc = fmt.Sprintf("%s:%d", f.File, f.Line)
		}
		fmt.Fprintf(&b, "\n%d. [%s] %s (%s)\n", i+1, strings.ToUpper(string(f.Severity)), f.Title, loc)
		if f.Detail != "" {
			fmt.Fprintf(&b, "   %s\n", f.Detail)
		}
		if f.Suggestion != "" {
			fmt.Fprintf(&b, "   Suggested fix: %s\n", f.Suggestion)
		}
	}
	return strings.TrimSpace(b.String()) + "\n"
}

