	// when they arrive; defaults to all high+medium selected (low off).
	findingSel []bool
	// fixStatus[i] is finding i's apply status: "" (pending), "fixing",
	// "fixed", "needs-human", or "failed". Sized with findings.
	fixStatus []string
	// applying is true while the fixer is running; applied is true once it's done.
	applying bool
	applied  bool
	// apply launches the fixer on the selected findings and returns a tea.Cmd
	// that yields a fixStreamMsg (live stream) or a fixDoneMsg (start error).
	// Injected (streaming headless fixer in production; a fake in tests). Nil
	// disables apply (Enter just exits).
	apply func(selected []Finding) tea.Cmd

	// Live-fix-stream state (set while applying). fixRowIdx is the index of the
	// synthetic "fix" row in rows whose buffer the stream fills (so the existing
	// drill-in renders it); -1 when no fix is in flight. fixVerify is called once
	// the stream closes to classify outcomes; fixSuccess tracks the terminal
	// Finished event's success.
	fixRowIdx  int
