// handleFixOneDone stores one finding's apply result (status + semantic summary
// + diff + counts) and advances the queue to the next selected finding.
func (m reviewTUIModel) handleFixOneDone(msg fixOneDoneMsg) (tea.Model, tea.Cmd) {
	if i := m.findingIndexByID(msg.id); i >= 0 {
		m.fixStatus[i] = msg.result.status
		m.fixSummary[i] = msg.result.summary
		m.fixDiff[i] = msg.result.diff
		m.fixAdded[i] = msg.result.added
		m.fixRemoved[i] = msg.result.removed
	}
	return m.advanceFixQueue()
}

// advanceFixQueue starts the next queued fix (marking it "fixing"), or marks the
// whole apply complete when the queue drains. Fixing one finding at a time gives
// each its own attributed diff.
func (m reviewTUIModel) advanceFixQueue() (tea.Model, tea.Cmd) {
	for len(m.fixQueue) > 0 {
		next := m.fixQueue[0]
		m.fixQueue = m.fixQueue[1:]
		if next < 0 || next >= len(m.findings) {
			continue
		}
		m.fixStatus[next] = fixStatusFixing
		return m, m.applyOne(m.findings[next])
	}
	m.applying = false
	m.applied = true
	return m, nil
}

// findingIndexByID returns the index of the finding with the given ID, or -1.
func (m reviewTUIModel) findingIndexByID(id string) int {
	for i, f := range m.findings {
		if f.ID == id {
			return i
		}
	}
	return -1
}

