// refreshFindingDetailContent (re)loads the focused finding's detail into the
// viewport: the why + suggested fix, plus the applied diff once it's been fixed
// (the on-demand full diff that keeps the findings panel itself concise).
func (m reviewTUIModel) refreshFindingDetailContent() reviewTUIModel {
	if m.findingIdx >= len(m.findings) {
		return m
	}
	m.detail.SetWidth(m.detailViewportWidth())
	m.detail.SetHeight(m.detailViewportHeight())
	width := m.detailViewportWidth()
	lines := buildFindingDetailLines(m.findings[m.findingIdx], width)
	if m.findingIdx < len(m.fixDiff) && m.fixDiff[m.findingIdx] != "" {
		lines = append(lines, "", "── applied diff ──")
		for _, dl := range strings.Split(strings.TrimRight(m.fixDiff[m.findingIdx], "\n"), "\n") {
			lines = append(lines, wrapDisplayWidth(dl, width)...)
		}
	}
	m.detail.SetContentLines(lines)
	m.detail.GotoTop()
	return m
}

