	out               io.Writer
	isTTY             bool
	canPrompt         bool
	agentNames        []string
	cancelRun         context.CancelFunc
	runContext        context.Context
	synthesisProvider SynthesisProvider
	promptYN          func(ctx context.Context, question string, def bool) (bool, error)
	perRunPrompt      string
	onSynthesisResult func(result string)
}

