package review

import (
	"context"
	"strings"
	"testing"
)

// fakeFixer records the finding it was asked to fix and returns a configurable
// outcome (or error).
type fakeFixer struct {
	outcome   FixOutcome
	err       error
	gotID     string
	callCount int
}

func (f *fakeFixer) FixOne(_ context.Context, finding Finding, _ string) (FixOutcome, error) {
	f.callCount++
	f.gotID = finding.ID
	return f.outcome, f.err
}

// verdictVerifier returns a fixed verdict per finding ID, modelling the post-fix
// re-verify: refuted → the issue is gone (fixed); confirmed → it still
// reproduces (needs-human).
type verdictVerifier map[string]Verdict

func (v verdictVerifier) Verify(_ context.Context, f Finding, _ string) (VerifyResult, error) {
	verdict, ok := v[f.ID]
	if !ok {
		verdict = VerdictConfirmed
	}
	return VerifyResult{Verdict: verdict}, nil
}

func TestApplyOneFix_ReVerifyGoneIsFixed(t *testing.T) {
	t.Parallel()
	// HIGH finding (skepticsFor(high) == 3, so verify runs); verifier refutes →
	// the issue is gone → fixed.
	f := Finding{ID: "gone", Severity: SeverityHigh, Title: "g"}
	fixer := &fakeFixer{outcome: FixOutcome{Summary: "added a guard", Success: true}}
	verifier := verdictVerifier{"gone": VerdictRefuted}

	res := applyOneFix(context.Background(), fixer, verifier, t.TempDir(), "HEAD", f)

	if res.status != fixStatusFixed {
		t.Errorf("status: got %q, want %q", res.status, fixStatusFixed)
	}
	if res.summary != "added a guard" {
		t.Errorf("summary: got %q", res.summary)
	}
	if fixer.callCount != 1 || fixer.gotID != "gone" {
		t.Errorf("fixer calls=%d id=%q, want 1/gone", fixer.callCount, fixer.gotID)
	}
}

func TestApplyOneFix_StillReproducesNeedsHuman(t *testing.T) {
	t.Parallel()
	f := Finding{ID: "stays", Severity: SeverityHigh, Title: "s"}
	fixer := &fakeFixer{outcome: FixOutcome{Success: true}}
	verifier := verdictVerifier{"stays": VerdictConfirmed}

	res := applyOneFix(context.Background(), fixer, verifier, t.TempDir(), "HEAD", f)

	if res.status != fixStatusNeedsHuman {
		t.Errorf("status: got %q, want %q", res.status, fixStatusNeedsHuman)
	}
}

func TestApplyOneFix_FixerErrorIsFailed(t *testing.T) {
	t.Parallel()
	fixer := &fakeFixer{err: context.DeadlineExceeded}
	verifier := verdictVerifier{} // must not be consulted on failure
	res := applyOneFix(context.Background(), fixer, verifier, t.TempDir(), "HEAD", Finding{ID: "a", Severity: SeverityHigh})
	if res.status != fixStatusFailed {
		t.Errorf("status: got %q, want %q", res.status, fixStatusFailed)
	}
}

func TestApplyOneFix_NilVerifierIsFixed(t *testing.T) {
	t.Parallel()
	fixer := &fakeFixer{outcome: FixOutcome{Success: true}}
	res := applyOneFix(context.Background(), fixer, nil, t.TempDir(), "HEAD", Finding{ID: "x", Severity: SeverityHigh})
	if res.status != fixStatusFixed {
		t.Errorf("status: got %q, want %q", res.status, fixStatusFixed)
	}
}

func TestComposeFixPrompt_IncludesFindingAndSummaryContract(t *testing.T) {
	t.Parallel()
	prompt := ComposeFixPrompt(Finding{
		Severity: SeverityHigh, Title: "SQL injection", File: "db.go", Line: 42,
		Detail: "user input concatenated", Suggestion: "use parameters",
	})
	for _, want := range []string{"SQL injection", "db.go:42", "HIGH", "user input concatenated", "use parameters", "SUMMARY:"} {
		if !strings.Contains(prompt, want) {
			t.Errorf("prompt missing %q\n---\n%s", want, prompt)
		}
	}
}

func TestParseFixSummary(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct{ name, in, want string }{
		{"trailing", "did some work\nSUMMARY: added a nil guard before deref", "added a nil guard before deref"},
		{"last wins", "SUMMARY: first\nmore\nSUMMARY: real one", "real one"},
		{"none", "no summary here", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := ParseFixSummary(tc.in); got != tc.want {
				t.Errorf("ParseFixSummary(%q) = %q, want %q", tc.in, got, tc.want)
			}
		})
	}
}

func TestBuildApplyFunc_NilFixerDisablesApply(t *testing.T) {
	t.Parallel()
	if buildApplyFunc(context.Background(), nil, nil, "", "") != nil {
		t.Error("buildApplyFunc with nil fixer should return nil (apply disabled)")
	}
}

func TestBuildApplyFunc_YieldsFixOneDoneMsg(t *testing.T) {
	t.Parallel()
	fixer := &fakeFixer{outcome: FixOutcome{Summary: "fixed it", Success: true}}
	apply := buildApplyFunc(context.Background(), fixer, nil, t.TempDir(), "HEAD")
	if apply == nil {
		t.Fatal("buildApplyFunc returned nil for a non-nil fixer")
	}
	cmd := apply(Finding{ID: "x", Severity: SeverityHigh})
	if cmd == nil {
		t.Fatal("apply returned a nil tea.Cmd")
	}
	msg, ok := cmd().(fixOneDoneMsg)
	if !ok {
		t.Fatalf("apply cmd yielded %T, want fixOneDoneMsg", cmd())
	}
	if msg.id != "x" || msg.result.status != fixStatusFixed {
		t.Errorf("msg: id=%q status=%q, want x/fixed", msg.id, msg.result.status)
	}
}

