package review

import (
	"context"
	"strings"
	"testing"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// fakeFixer returns a pre-seeded event stream (or a start error). It records the
// request so tests can assert prompt composition.
type fakeFixer struct {
	events    []reviewtypes.Event
	startErr  error
	gotReq    FixRequest
	callCount int
}

func (f *fakeFixer) Fix(_ context.Context, req FixRequest) (<-chan reviewtypes.Event, error) {
	f.callCount++
	f.gotReq = req
	if f.startErr != nil {
		return nil, f.startErr
	}
	ch := make(chan reviewtypes.Event, len(f.events))
	for _, ev := range f.events {
		ch <- ev
	}
	close(ch)
	return ch, nil
}

// verdictVerifier returns a fixed verdict per finding ID, modelling the post-fix
// re-verify: refuted → the issue is gone (fixed); confirmed → it still
// reproduces (needs-human).
type verdictVerifier map[string]Verdict

