	verdict, ok := v[f.ID]
	if !ok {
		verdict = VerdictConfirmed
	}
	return VerifyResult{Verdict: verdict}, nil
}

func TestClassifyOutcomes_ReVerifySplitsFixedAndNeedsHuman(t *testing.T) {
	t.Parallel()
