// TestModel_PerFindingApplyQueue drives the real buildApplyFunc per-finding
// queue: Enter fixes selected findings one at a time (each → fixOneDoneMsg),
// rows fill with the semantic summary, and the panel renders it.
func TestModel_PerFindingApplyQueue(t *testing.T) {
	t.Parallel()
	m := newReviewTUIModel([]string{"codex"}, func() {}, nil)
	m.termWidth, m.termHeight = 100, 30
	mm, _ := m.Update(findingsMsg{findings: []Finding{
		{ID: "h", Severity: SeverityHigh, File: "a.go", Line: 1, Title: "boom", Agent: "codex"},
		{ID: "m", Severity: SeverityMedium, File: "b.go", Line: 2, Title: "leak", Agent: "claude"},
	}})
	m = mustModel(t, mm)
	mm, _ = m.Update(runFinishedMsg{summary: reviewtypes.RunSummary{AgentRuns: []reviewtypes.AgentRun{{Name: "codex", Status: reviewtypes.AgentStatusSucceeded}}}})
	m = mustModel(t, mm)

	// Real apply func over a fake per-finding fixer (summary + success) and nil
	// verifier (→ optimistic fixed).
	fixer := &fakeFixer{outcome: FixOutcome{Summary: "added `if b == 0 { return 0 }` before the divide", Success: true}}
	m.applyOne = buildApplyFunc(context.Background(), fixer, nil, t.TempDir(), "HEAD")

	mm, cmd := m.Update(testKey(tea.KeyEnter)) // enter → start queue
	m = mustModel(t, mm)
	if !m.applying || m.fixStatus[0] != fixStatusFixing || cmd == nil {
		t.Fatalf("enter should start applying first finding, got applying=%v status0=%q cmd=%v", m.applying, m.fixStatus[0], cmd != nil)
	}

	// Drive the per-finding queue to completion (one fixOneDoneMsg per finding).
	for range 10 {
		if cmd == nil {
			break
		}
		mm, cmd = m.Update(cmd())
		m = mustModel(t, mm)
		if m.applied {
			break
		}
	}
	if !m.applied {
		t.Fatal("queue never reached applied")
	}
	if m.fixStatus[0] != fixStatusFixed || m.fixStatus[1] != fixStatusFixed {
		t.Fatalf("both findings should be fixed, got %q / %q", m.fixStatus[0], m.fixStatus[1])
	}
	if fixer.callCount != 2 {
		t.Fatalf("fixer should run once per selected finding, got %d", fixer.callCount)
	}
	// The semantic summary renders inline in the findings panel.
	out := m.dashboardView()
	if !strings.Contains(out, "fixed ✓") || !strings.Contains(out, "before the divide") {
		t.Fatalf("expected fixed status + semantic summary:\n%s", out)
	}
	t.Logf("\n%s", out)
}

