func (m reviewTUIModel) pipelineLines() []string {
	if len(m.rows) == 0 && len(m.phases) == 0 {
		return nil
	}
	lines := []string{"", "PIPELINE"}
	findSt := m.phases[PhaseFind]
	findMark, findDetail := "·", findSt.detail
	switch {
	case findSt.done:
		findMark = "✓"
	case m.anyAgentRunning():
		findMark = m.spinner.View()
		findDetail = "reviewing…"
	}
	lines = append(lines, fmt.Sprintf("  %s %-11s %s", findMark, "find", findDetail))
	for _, p := range []Phase{PhaseVerify, PhaseSynthesize} {
		st := m.phases[p]
		mark := "·"
		if st.done {
			mark = "✓"
		}
		lines = append(lines, fmt.Sprintf("  %s %-11s %s", mark, string(p), st.detail))
	}
	return lines
}

