// toolActivityLabel renders a compact live-activity string for a tool call,
// e.g. "→ Read db.go" or "→ Grep "func New"". Args are JSON from the agent;
// we pull a human-friendly value (file_path / path / pattern / command / the
// first string field) when present, else fall back to the raw collapsed args.
func toolActivityLabel(tc reviewtypes.ToolCall) string {
	name := strings.TrimSpace(tc.Name)
	if name == "" {
		name = "tool"
	}
	arg := toolActivityArg(tc.Args)
	if arg == "" {
		return "→ " + name
	}
	return "→ " + name + " " + arg
}

// toolActivityArg extracts a short, human-friendly argument from a tool call's
// JSON args. Falls back to collapsed raw args when no known key is present.
func toolActivityArg(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}
	var fields map[string]any
	if err := json.Unmarshal([]byte(raw), &fields); err == nil {
		for _, key := range []string{"file_path", "path", "pattern", "query", "command", "url"} {
			if v, ok := fields[key].(string); ok && strings.TrimSpace(v) != "" {
				return stringutil.CollapseWhitespace(sanitizeDisplayText(v))
			}
		}
	}
	return stringutil.CollapseWhitespace(sanitizeDisplayText(raw))
}

