func TestToolActivityLabel(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name string
		tc   reviewtypes.ToolCall
		want string
	}{
		{"file_path", reviewtypes.ToolCall{Name: "Read", Args: `{"file_path":"db.go"}`}, "→ Read db.go"},
		{"pattern", reviewtypes.ToolCall{Name: "Grep", Args: `{"pattern":"func New"}`}, "→ Grep func New"},
		{"command", reviewtypes.ToolCall{Name: "Bash", Args: `{"command":"go test ./..."}`}, "→ Bash go test ./..."},
		{"no args", reviewtypes.ToolCall{Name: "Glob"}, "→ Glob"},
		{"raw fallback", reviewtypes.ToolCall{Name: "X", Args: "not json"}, "→ X not json"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := toolActivityLabel(tc.tc); got != tc.want {
				t.Errorf("toolActivityLabel = %q, want %q", got, tc.want)
			}
		})
	}
}

