// fixSummaryLine renders the indented semantic-summary sub-line for finding i
// once it has been fixed (or flagged needs-human), e.g.
//
//	└ added `if b == 0 { return 0 }` before the divide · +3 −1   [o] diff
//
// Returns "" when there is nothing to show yet (pending / fixing / failed).
func (m reviewTUIModel) fixSummaryLine(i int) string {
	if i >= len(m.fixStatus) || (m.fixStatus[i] != fixStatusFixed && m.fixStatus[i] != fixStatusNeedsHuman) {
		return ""
	}
	summary := "change applied"
	if i < len(m.fixSummary) {
		if s := strings.TrimSpace(m.fixSummary[i]); s != "" {
			summary = s
		}
	}
	counts := ""
	if i < len(m.fixAdded) && (m.fixAdded[i] > 0 || m.fixRemoved[i] > 0) {
		counts = fmt.Sprintf(" · +%d −%d", m.fixAdded[i], m.fixRemoved[i])
	}
	hint := ""
	if i < len(m.fixDiff) && m.fixDiff[i] != "" {
		hint = "   [o] diff"
	}
	return fmt.Sprintf("      └ %s%s%s", summary, counts, hint)
}

