// shows the semantic result (what changed); before a fix it shows, for the
// focused finding only (to keep the list compact), a brief "what would change"
// preview from the reviewer's suggestion.
func (m reviewTUIModel) findingSubLine(i int, f Finding) string {
	if i < len(m.fixStatus) && (m.fixStatus[i] == fixStatusFixed || m.fixStatus[i] == fixStatusNeedsHuman) {
